package csharp

import (
	"bytes"
	"regexp"

	"github.com/archstats/archstats/core/file"
)

// Conventions are .NET's: test projects, the <auto-generated> header its
// tools write, LibMan's wwwroot/lib, and namespaces that are directories.
func Conventions() file.Conventions {
	return file.Conventions{
		Name:           "dotnet",
		IsTest:         dotnetTestProject.MatchString,
		IsGenerated:    func(head []byte) bool { return bytes.Contains(head, []byte("<auto-generated")) },
		ThirdPartyDirs: []string{"wwwroot/lib/"},
		PackageDirExts: []string{".cs", ".vb", ".fs"},
	}
}

// A .NET test project: Nop.Tests, Foo.UnitTests, Bar.IntegrationTests.
var dotnetTestProject = regexp.MustCompile(`(^|/)[^/]*\.(Unit|Integration|Functional|Acceptance)?Tests?(/|$)`)
